\documentclass[11pt]{amsart}
\usepackage{amsmath,amssymb,amsthm}
\usepackage[margin=1in]{geometry}
\usepackage{hyperref}

\newtheorem{theorem}{Theorem}[section]
\newtheorem{proposition}[theorem]{Proposition}
\newtheorem{corollary}[theorem]{Corollary}
\newtheorem{conjecture}[theorem]{Conjecture}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\newtheorem{remark}[theorem]{Remark}

\newcommand{\Z}{\mathbb{Z}}
\newcommand{\R}{\mathbb{R}}
\newcommand{\T}{\mathbb{T}}
\newcommand{\norm}[1]{\lVert #1 \rVert}

\title{Closed Geodesics and the Wrapping Lattice of the Flat Three-Torus}
\author{Aristotle}
\date{2026-07-12}

\begin{document}
\begin{abstract}
We give a self-contained account of the geodesic and homotopical structure of the
flat three-torus $\T^3 = (\R/\Z)^3$, regarded as a model of a spatially closed
(``donut-shaped'') universe. We prove: (i) every straight line with integer
direction projects to a closed geodesic of period one; (ii) every nonzero integer
direction yields a genuinely non-constant loop; (iii) the covering-translation
group equals the integer lattice, so $\pi_1(\T^3)\cong\Z^3$ with three independent
generators; and (iv) the assignment of an integer direction to the homotopy class
of its geodesic is injective, giving a full $\Z^3$ of inequivalent closed
geodesics. We develop the wrapping (length) spectrum as a lattice-norm multiset,
connect it to observational cosmology, and record the conjecture that the Weeks
manifold, of volume $\approx 0.9427073627769277$, uniquely minimizes volume among
closed orientable hyperbolic three-manifolds.
\end{abstract}

\maketitle

\section{Introduction}
The global topology of the universe is not fixed by the (local) Einstein
equations. A spatial slice that is everywhere flat may still be finite and
multiply connected; the simplest such model is the three-torus $\T^3$, the
``donut-shaped'' universe. There a traveler on a straight path can return home,
and light can arrive along several geodesics, producing observable repetitions.
We isolate and prove the mathematical core of this picture: closedness and
non-triviality of integer geodesics, the identification $\pi_1(\T^3)\cong\Z^3$
via the covering-translation group, and an injective direction-to-class map. We
then build the length spectrum and frame the hyperbolic minimal-volume problem.

\section{Definitions and setup}
Let $\R/\Z$ be the circle of circumference one, with $[r]$ the class of
$r\in\R$. The basic fact is $[r]=0 \iff r\in\Z$, and $[r+m]=[r]$ for $m\in\Z$.

\begin{definition}[Flat three-torus]
$\T^3 := (\R/\Z)^3$, an abelian group under coordinatewise addition, with the
flat metric inherited from $\R^3$.
\end{definition}

\begin{definition}[Covering projection]
$\pi:\R^3\to\T^3$, $\pi(x_0,x_1,x_2)=([x_0],[x_1],[x_2])$, a local isometry and
covering map with universal cover $\R^3$.
\end{definition}

\begin{definition}[Integer geodesic]
For $n\in\Z^3$, $\gamma_n:\R\to\T^3$, $\gamma_n(t)=\pi(tn)=([tn_0],[tn_1],[tn_2])$,
the projection of the straight line $t\mapsto tn$, hence a flat geodesic.
\end{definition}

\begin{definition}[Wrapping lattice]
The image of $\iota:\Z^3\hookrightarrow\R^3$, $\iota(n)=(n_0,n_1,n_2)$, the group
of covering translations of $\pi$.
\end{definition}

\section{Closed geodesics}
\begin{theorem}[Closedness / period one]
For every $n\in\Z^3$ and $t\in\R$, $\gamma_n(t+1)=\gamma_n(t)$.
\end{theorem}
\begin{proof}
Coordinatewise $(t+1)n_i = tn_i + n_i$ with $n_i\in\Z$, so
$[(t+1)n_i]=[tn_i+n_i]=[tn_i]$ since adding an integer does not change the class.
This holds in each coordinate.
\end{proof}

\begin{remark}
Periodicity alone is insufficient: the constant path $\gamma_0$ is period-one. The
next theorem rules out this degeneracy.
\end{remark}

\begin{theorem}[Non-triviality of wrapping]
If $n\in\Z^3$ is nonzero, $\gamma_n$ is non-constant: there is $t$ with
$\gamma_n(t)\neq\gamma_n(0)$.
\end{theorem}
\begin{proof}
Pick $i$ with $n_i\neq 0$ and set $t^\ast=\tfrac{1}{2n_i}$. Then
$[t^\ast n_i]=[\tfrac12]$. Since $\tfrac12\notin\Z$, we have $[\tfrac12]\neq 0$
(it is the unique order-two element of the circle), so
$\gamma_n(t^\ast)\neq\gamma_n(0)$.
\end{proof}

\begin{corollary}
$\T^3$ contains infinitely many non-constant closed geodesics, one for each
nonzero $n\in\Z^3$; that they are distinct homotopy classes is Theorem~5.2.
\end{corollary}

\section{The wrapping lattice and $\pi_1(\T^3)\cong\Z^3$}
\begin{theorem}[Kernel of the covering projection]
For $x\in\R^3$, $\pi(x)=0 \iff x_i\in\Z$ for every $i$; equivalently
$\ker\pi=\iota(\Z^3)$.
\end{theorem}
\begin{proof}
$\pi(x)=0$ means $[x_i]=0$ for all $i$, i.e. $x_i\in\Z$; assembling gives
$x=\iota(m)$ with $m\in\Z^3$, and conversely every $\iota(m)$ projects to $0$.
\end{proof}

\begin{theorem}[Faithfulness]
$\iota:\Z^3\to\R^3$ is injective.
\end{theorem}
\begin{proof}
$\iota(a)=\iota(b)$ gives $a_i=b_i$ as reals, hence as integers.
\end{proof}

\begin{theorem}[$\pi_1(\T^3)\cong\Z^3$]
The covering-translation group equals $\iota(\Z^3)$ and $\iota$ is an injective
homomorphism, so
\[ \pi_1(\T^3)\;\cong\;\ker\pi\;=\;\iota(\Z^3)\;\cong\;\Z^3. \]
\end{theorem}
\begin{proof}
By Theorem~4.1, $\ker\pi=\iota(\Z^3)$; by Theorem~4.2, $\iota$ is an injective
homomorphism, hence an isomorphism onto its image. For a universal covering the
deck group is canonically $\pi_1$.
\end{proof}

\begin{theorem}[Three independent families of wrapping]
The standard directions $e_0,e_1,e_2$ are $\Z$-linearly independent and generate
$\iota(\Z^3)$; hence $\pi_1(\T^3)$ has exactly three independent generators
($b_1(\T^3)=3$).
\end{theorem}
\begin{proof}
A relation $\sum_i c_ie_i=0$ reads $c_j=0$ coordinatewise; every integer vector is
$\sum_i n_ie_i$.
\end{proof}

\section{Homotopy classes of closed geodesics}
\begin{definition}[Homotopy class map]
Let $c:\Z^3\to\ker\pi$, $c(n)=\iota(n)$. Then $c(n)\in\ker\pi$ by Theorem~4.1 and
$\pi(c(n))=\gamma_n(1)$: the lift of $\gamma_n$ from the origin ends at $\iota(n)$.
\end{definition}

\begin{theorem}[Injectivity; infinitely many geodesics]
$c$ is injective, so distinct integer directions give inequivalent closed
geodesics and $\T^3$ carries a full $\Z^3$ of homotopy classes.
\end{theorem}
\begin{proof}
$c(a)=c(b)\Rightarrow\iota(a)=\iota(b)\Rightarrow a=b$ by Theorem~4.2.
\end{proof}

\begin{remark}[Primitivity]
$n$ is primitive if $\gcd(n_0,n_1,n_2)=1$. Non-primitive $n=dm$ retraces $m$'s
image $d$ times; the primitive closed geodesics biject with primitive lattice
vectors.
\end{remark}

\section{The wrapping spectrum}
For a flat torus $\R^3/L$ the length of the geodesic in the class $v\in L$ is
$\norm{v}$.

\begin{definition}[Wrapping spectrum, systole]
$\mathcal{L}(L)=\{\norm{v}:v\in L\setminus\{0\}\}$ and
$\mathrm{sys}(L)=\min_{v\neq 0}\norm{v}$.
\end{definition}

\begin{proposition}[Cubic spectrum]
For $L=\Z^3$ the distinct lengths are $\sqrt{k}$ with $k$ a sum of three squares
(all $k$ not of the form $4^a(8b+7)$, by Legendre's theorem); the systole is $1$;
the count of geodesics of length $\sqrt{k}$ is $r_3(k)$.
\end{proposition}
\begin{proof}
Lengths are $\sqrt{n_0^2+n_1^2+n_2^2}$; the attainable $k$ and their
multiplicities are governed by the three-square theorem and $r_3(k)$; the least
nonzero norm is $1$.
\end{proof}

\begin{conjecture}[Spectral rigidity of flat tori]
The primitive-geodesic lengths of $\R^3/L$ equal the primitive-lattice norms, and
the wrapping spectrum is a complete isometry invariant up to finitely many
exceptions.
\end{conjecture}

\section{Applications: cosmic topology}
If a spatial slice is a flat torus, multiple geodesics connect any two points, so
one source yields several images separated by lattice translations $\iota(n)$; the
histogram of separations peaks at $\mathcal{L}(L)$ (cosmic crystallography).
If the last-scattering sphere exceeds the systole it self-intersects across the
identifications, giving matched temperature circles fixed by the deck
translations; the three independent generators predict three fundamental
matched-circle families.

\section{The minimal-volume problem for hyperbolic universes}
By Mostow rigidity a closed hyperbolic three-manifold has its volume determined by
its topology, so ``smallest curved universe'' is well posed.
\begin{conjecture}[Minimality of the Weeks manifold]
Among closed orientable hyperbolic three-manifolds, the Weeks manifold uniquely
attains the minimal volume $V_{\mathrm{Weeks}}\approx 0.9427073627769277$, and
none has volume below $0.94$.
\end{conjecture}
The Weeks manifold arises by $(5,1)$ and $(5,2)$ Dehn surgery on the Whitehead
link; it is arithmetic and its volume is a value of the Lobachevsky function. The
set of volumes is well-ordered (Thurston--J\o rgensen), so a minimum exists.

\section{Discussion}
The flat-torus results are elementary but airtight: closedness is ``adding an
integer is invisible on the circle,'' non-triviality is ``one-half is not an
integer,'' and $\pi_1\cong\Z^3$ is ``projecting to zero means all coordinates are
integers.'' The wrapping spectrum turns geometry into number theory and connects
to cosmology; the minimal-volume problem points to hyperbolic rigidity.

\section*{Future directions}
\begin{enumerate}
\item Systolic wrapping spectrum of the flat torus (primitive lengths $=$
primitive lattice norms; systole $=$ minimal lattice norm).
\item Three-family rigidity of $\pi_1$ (finite cover by $\T^3$; number of families
$=$ first Betti number; compare Bieberbach classification).
\item Closed timelike curves from a temporal wrapping factor
$\R/\tau\Z$: timelike classes of $\Z^3\times\Z$.
\item Minimality of the Weeks manifold (Conjecture~9.1).
\end{enumerate}

\begin{thebibliography}{9}
\bibitem{Thurston} W.~Thurston, \emph{The Geometry and Topology of Three-Manifolds}.
\bibitem{Weeks} J.~Weeks, \emph{The Shape of Space}.
\bibitem{Rucker} R.~Rucker, \emph{The Fourth Dimension}.
\bibitem{GMM} D.~Gabai, R.~Meyerhoff, P.~Milley, work on minimal-volume hyperbolic
three-manifolds.
\bibitem{Cosmic} M.~Lachi\`eze-Rey, J.-P.~Luminet, \emph{Cosmic Topology}.
\end{thebibliography}

\end{document}

