    """k = a^2+b^2+c^2  ->  r_3(k), the number of geodesics of length sqrt(k)."""
    counts: Dict[int, int] = {}
    rng = range(-radius, radius + 1)
    for a in rng:
        for b in rng:
            for c in rng:
                if (a, b, c) != (0, 0, 0):
                    k = a * a + b * b + c * c
                    counts[k] = counts.get(k, 0) + 1
    return counts


def three_square(k: int) -> bool:
    """Legendre: k is a sum of three squares iff not of form 4^a(8b+7)."""
    while k % 4 == 0:
        k //= 4
    return k % 8 != 7


