function PRIMITIVE_GEODESICS(k):
    out <- empty list; r <- floor(sqrt(k))
    for a in -r..r:
        for b in -r..r:
            c2 <- k - a*a - b*b
            if c2 < 0: continue
            c <- isqrt(c2)
            if c*c != c2: continue
            for cc in {c, -c}:
                v <- (a,b,cc)
                if v != 0 and gcd(|a|,|b|,|cc|) = 1: append v to out
    return out

